"use client";

import * as React from "react";
import { cn } from "../../lib/utils.js";

/**
 * Clustering tree where every leaf sits at the same depth, regardless of
 * branch length — the visual signature of taxonomies, phylogenetic trees,
 * and hierarchical-clustering output. Backed by d3-hierarchy's `cluster`
 * layout (distinct from `tree`, which packs leaves variably).
 *
 * Heavy peer: requires `d3-hierarchy` (~3 KB gzip).
 *
 * @example
 * <Dendrogram
 *   root={{
 *     id: "root", label: "Animals",
 *     children: [
 *       { id: "mammals", label: "Mammals", children: [
 *         { id: "cat", label: "Cat" },
 *         { id: "dog", label: "Dog" },
 *       ]},
 *       { id: "birds", label: "Birds", children: [{ id: "robin", label: "Robin" }] },
 *     ],
 *   }}
 * />
 */
export type DendrogramNode = {
	id: string;
	label: string;
	children?: DendrogramNode[];
};

export interface DendrogramProps extends Omit<React.SVGAttributes<SVGSVGElement>, "children"> {
	/** Root of the hierarchy. */
	root: DendrogramNode;
	/** "horizontal" runs root-to-leaves left→right; "vertical" runs top→bottom. Default "horizontal". */
	orientation?: "horizontal" | "vertical";
	/** "step" draws right-angle elbow links (taxonomy aesthetic); "diagonal" uses smooth Bezier. Default "step". */
	linkShape?: "step" | "diagonal";
	/** Pixel width of the rendered SVG. Default 600. */
	width?: number;
	/** Pixel height of the rendered SVG. Default 400. */
	height?: number;
	/** Fired when a leaf is clicked. */
	onLeafClick?: (node: DendrogramNode) => void;
}

interface LaidOutNode {
	node: DendrogramNode;
	x: number;
	y: number;
	depth: number;
	isLeaf: boolean;
}

interface LaidOutLink {
	source: { x: number; y: number };
	target: { x: number; y: number };
	id: string;
}

type D3HierarchyMod = typeof import("d3-hierarchy");

function Dendrogram({
	root,
	orientation = "horizontal",
	linkShape = "step",
	width = 600,
	height = 400,
	onLeafClick,
	className,
	...rest
}: DendrogramProps) {
	const [d3h, setD3h] = React.useState<D3HierarchyMod | null>(null);

	React.useEffect(() => {
		let cancelled = false;
		void import("d3-hierarchy").then((mod) => {
			if (!cancelled) setD3h(mod);
		});
		return () => {
			cancelled = true;
		};
	}, []);

	if (!d3h) {
		return (
			<div
				data-hex-dendrogram-loading
				aria-busy="true"
				className={cn("inline-block bg-muted/20", className)}
				style={{ width, height }}
			/>
		);
	}

	const { nodes, links } = layout(d3h, root, orientation, width, height);
	const leafCount = nodes.filter((n) => n.isLeaf).length;
	const desc = `Dendrogram with ${leafCount} leaves, rooted at "${root.label}"`;

	return (
		<svg
			{...rest}
			data-hex-dendrogram
			data-orientation={orientation}
			data-link-shape={linkShape}
			role="img"
			width={width}
			height={height}
			viewBox={`0 0 ${width} ${height}`}
			className={cn("block", className)}
		>
			<title>Dendrogram</title>
			<desc>{desc}</desc>
			<g data-hex-dendrogram-links>
				{links.map((l) => (
					<path
						key={l.id}
						d={linkPath(l, orientation, linkShape)}
						fill="none"
						stroke="hsl(var(--muted-foreground))"
						strokeOpacity={0.8}
						strokeWidth={1}
					/>
				))}
			</g>
			<g data-hex-dendrogram-nodes>
				{nodes.map((n) => (
					<g
						key={n.node.id}
						data-hex-dendrogram-node
						data-leaf={n.isLeaf ? "true" : "false"}
						data-depth={n.depth}
						transform={`translate(${n.x},${n.y})`}
						style={n.isLeaf && onLeafClick ? { cursor: "pointer" } : undefined}
						onClick={n.isLeaf && onLeafClick ? () => onLeafClick(n.node) : undefined}
					>
						<circle
							r={n.isLeaf ? 3 : 2}
							fill={n.isLeaf ? "hsl(var(--primary))" : "hsl(var(--muted-foreground))"}
						/>
						{n.isLeaf ? (
							<text
								x={orientation === "horizontal" ? 6 : 0}
								y={orientation === "horizontal" ? 4 : 14}
								textAnchor={orientation === "horizontal" ? "start" : "middle"}
								fontSize={11}
								fill="hsl(var(--foreground))"
								style={{ paintOrder: "stroke" }}
								stroke="hsl(var(--background))"
								strokeWidth={3}
								strokeLinejoin="round"
							>
								{n.node.label}
							</text>
						) : null}
					</g>
				))}
			</g>
		</svg>
	);
}

function layout(
	d3h: D3HierarchyMod,
	root: DendrogramNode,
	orientation: "horizontal" | "vertical",
	width: number,
	height: number,
): { nodes: LaidOutNode[]; links: LaidOutLink[] } {
	const hierarchy = d3h.hierarchy<DendrogramNode>(root);
	const clusterFn = d3h.cluster<DendrogramNode>();
	if (orientation === "horizontal") {
		clusterFn.size([height - 32, width - 120]);
	} else {
		clusterFn.size([width - 32, height - 64]);
	}
	// cluster(hierarchy) returns HierarchyPointNode<T> with typed x/y.
	const layoutRoot = clusterFn(hierarchy);

	const nodes: LaidOutNode[] = [];
	layoutRoot.each((d) => {
		const isLeaf = !d.children || d.children.length === 0;
		if (orientation === "horizontal") {
			nodes.push({ node: d.data, x: d.y + 16, y: d.x + 16, depth: d.depth, isLeaf });
		} else {
			nodes.push({ node: d.data, x: d.x + 16, y: d.y + 16, depth: d.depth, isLeaf });
		}
	});

	const links: LaidOutLink[] = layoutRoot.links().map((link, i) => {
		if (orientation === "horizontal") {
			return {
				source: { x: link.source.y + 16, y: link.source.x + 16 },
				target: { x: link.target.y + 16, y: link.target.x + 16 },
				id: `l-${i}`,
			};
		}
		return {
			source: { x: link.source.x + 16, y: link.source.y + 16 },
			target: { x: link.target.x + 16, y: link.target.y + 16 },
			id: `l-${i}`,
		};
	});

	return { nodes, links };
}

function linkPath(
	link: LaidOutLink,
	orientation: "horizontal" | "vertical",
	linkShape: "step" | "diagonal",
): string {
	const { source: s, target: t } = link;
	if (linkShape === "step") {
		if (orientation === "horizontal") {
			return `M${s.x},${s.y} H${t.x} V${t.y}`;
		}
		return `M${s.x},${s.y} V${t.y} H${t.x}`;
	}
	if (orientation === "horizontal") {
		const mx = (s.x + t.x) / 2;
		return `M${s.x},${s.y} C${mx},${s.y} ${mx},${t.y} ${t.x},${t.y}`;
	}
	const my = (s.y + t.y) / 2;
	return `M${s.x},${s.y} C${s.x},${my} ${t.x},${my} ${t.x},${t.y}`;
}

export { Dendrogram };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex UI: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}
